insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$prescription$pci$, $pci$Prescription$pci$, $pci$Any recommendation, treatment, action plan, best choice or behavioral direction. Prescription lies outside the PCI Engine; "observation → prescription" is a prohibited transformation.$pci$, $pci$derived$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$stop-boundary$pci$, $pci$STOP boundary$pci$, $pci$The point at which PCI processing ends: after the observational report. Any choice, action, strategy, intervention, recommendation, or behavioral direction that follows belongs outside the PCI Engine.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$input$pci$, $pci$Input$pci$, $pci$The first operation. What actually occurred, or what material is present, before explaining what it means. Principle: preserve the raw material before explanation.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$decomposition$pci$, $pci$Decomposition$pci$, $pci$The second operation. Separating event, behavior, interpretation, emotion, judgment, assumption, context, identity attribution, and unknown — categories commonly experienced as a single narrative.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$contextual-comparison$pci$, $pci$Contextual Comparison$pci$, $pci$The third operation. Where something structurally similar has appeared before, and what was the same or different about the context. Compares without treating similarity as causation or sameness.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$pattern-detection$pci$, $pci$Pattern Detection$pci$, $pci$The fourth operation. What appears to repeat across the available material, and under what conditions. Reports recurrence without converting it into identity.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$contradiction-detection$pci$, $pci$Contradiction Detection$pci$, $pci$The fifth operation. What parts of the material appear inconsistent, incompatible, revised, or unresolved when compared. Exposes tension without forcing resolution.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$evidentiary-separation$pci$, $pci$Evidentiary Separation$pci$, $pci$The sixth operation. What is directly evidenced, what is interpreted or inferred, what remains hypothetical or symbolic, and what is presently unknown. Protects epistemic classes.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$observational-report$pci$, $pci$Observational Report$pci$, $pci$The seventh operation. What can actually be observed without deciding what the person should think, become, choose, or do. Returns visibility and stops.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
