insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$pattern-adoption$pci$, $pci$Pattern Adoption$pci$, $pci$An analytical sub-engine: Signal → Recurrence → Reinforcement → Defaulting → Integration → Identification → Preservation → Visibility → Revision. Not a personality label; it does not infer origin from recurrence alone.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$observer-observed$pci$, $pci$Observer / Observed$pci$, $pci$Distinguishing the observed event from observer position, attention, frames, expectation, meaning assignment, identity involvement, state and self-observation — without pathologizing the observer.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$meta-observational-integrity-audit$pci$, $pci$Meta-Observational Integrity Audit$pci$, $pci$One controlled self-audit before a report is finalised, checking inference inflation, interpretation leakage, lens contamination, identity inflation, narrative coherence bias, pattern overfitting, context collapse, confirmation loops, counter-hypotheses and disconfirming evidence.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$on-the-contrary$pci$, $pci$On the Contrary$pci$, $pci$A contained examination of an apparent error, imbalance, problem, unwanted event or contradiction within a wider relational system: Identified Error → Implied Expectation → Missing Variables → System Relationship → Contrary Position → Balance.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$balance$pci$, $pci$Balance$pci$, $pci$Relationship within a system. Balance does not automatically mean fairness, desirability, approval, justice, health, morality, correctness, comfort, or forced positivity.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$relational-intelligence$pci$, $pci$Relational intelligence$pci$, $pci$With explicit permission, comparing current material against previous material through traceable relationship types such as RELATED TO, CONTRADICTS, REPEATS and CHANGES UNDER.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$graph-edge$pci$, $pci$Graph edge$pci$, $pci$A recorded, visible relationship between two pieces of material. It is not automatically a causal mechanism.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$longitudinal-comparison$pci$, $pci$Longitudinal comparison$pci$, $pci$Comparison of current material with the user’s earlier material. Off unless the user explicitly enables it, and can be disabled at any time.$pci$, $pci$derived$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$cognitive-twin$pci$, $pci$Cognitive Twin$pci$, $pci$An advanced, opt-in, revisable structural model generated from available material. Not a declaration of the user’s true self or essence; every element links to supporting and contradicting observations.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$causal-hypothesis$pci$, $pci$Causal hypothesis$pci$, $pci$Observed sequence → candidate mechanism → supporting evidence → alternative mechanism → disconfirming evidence → confidence. Sequence is not causation; causal relationships remain hypotheses unless independently demonstrated.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$self-correcting-theory$pci$, $pci$Self-correcting theory$pci$, $pci$Previous interpretation → new evidence → compatibility test → support / narrow / contradict / dissolve → new model version. Earlier versions are preserved.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$constitutional-invariant$pci$, $pci$Constitutional invariant$pci$, $pci$One of fifteen prohibited transformations — such as correlation → causation, behavior → permanent identity, or observation → prescription — enforced in contracts, schemas, validators, tests and report language.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$multi-lens-analysis$pci$, $pci$Multi-lens analysis$pci$, $pci$Optional analysis through separate lenses (cognitive, behavioral, systems, relational, identity, creative-process, Jungian, mythological, philosophical), each producing findings under its own label before comparison.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
insert into public.glossary_terms (slug, term, definition, canon_status, status) values ($pci$lens-isolation$pci$, $pci$Lens isolation$pci$, $pci$Each lens keeps its findings, and their epistemic class, separate until cross-lens comparison. Symbolic resonance does not become empirical evidence.$pci$, $pci$canonical$pci$, 'published') on conflict (slug) do nothing;
